INSERT INTO legal_concepts (id, concept, category, subcategory, definition_simple, real_example, regulation, jurisprudencia, video_url, key_points) VALUES
('DP-001', 'Capacidad Procesal', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Aptitud legal para comparecer vßlidamente en juicio, sea por sÝ o mediante representante legal. Difiere de la capacidad para ser parte, que es la idoneidad para figurar como sujeto en el proceso (toda persona natural o jurÝdica la tiene)', 'la capacidad procesal exige mayorÝa de edad o habilitaci¾n legal.', 'Ej.: Un menor de edad debe litigar representado por su tutor, careciendo de capacidad procesal propia.', 'Art. 7 C¾digo de Procedimiento Civil (CPC) (los incapaces solo act·an por representante)', '', '[]'),
('DP-002', 'Litisconsorcio', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Situaci¾n en que varias personas act·an como demandantes o demandados en un mismo juicio, compartiendo un interÚs jurÝdico com·n. Puede ser voluntario (partes deciden litigar conjuntamente) o necesario (la ley exige la presencia de todos los interesados).', 'Ej.: Dos copropietarios presentan juntos una demanda (litisconsorcio activo) o un deudor y su codeudor son demandados simultßneamente (litisconsorcio pasivo) en un mismo proceso.', 'Art. 18 CPC (autoriza litigar conjuntamente cuando la acci¾n emane de un mismo hecho o derecho)', '', '', '["Debate doctrinal sobre litisconsorcio necesario: algunos sostienen que la sentencia es nula si no comparecen todos los sujetos jurÝdicamente ligados (p. ej., todos los cotitulares de un derecho real)", "Otros estiman que el juez puede instar la integraci¾n de tales partes ausentes antes de fallar, privilegiando la economÝa procesal sobre formalidades ."]'),
('DP-003', 'Patrocinio y Poder', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Regla general que exige que las partes comparezcan en juicio representadas por un abogado habilitado (patrocinio) y mediante un mandato judicial otorgado (poder). El patrocinio se acredita con la firma del abogado en los escritos, y el poder con el instrumento que faculta al mandatario para actuar en nombre de la parte.', 'Ej.: En una demanda civil de mayor cuantÝa, el demandante otorga poder ante notario a un abogado y este patrocina el escrito inicial, cumpliendo con la exigencia legal.', 'Arts. 1, 4, 6 CPC (obligatoriedad de comparecer por medio de abogado patrocinante y mandatario con poder suficiente)', '', '', '["Tensi¾n prßctica: la ausencia de poder o patrocinio vßlido puede llevar a la nulidad de lo obrado, pero la jurisprudencia tiende a conceder oportunidades de subsanar (aportar poder dentro de plazo) para no sacrificar el fondo por defectos formales", "Discusi¾n doctrinal sobre si el vicio de falta de patrocinio es saneable o causa de inadmisibilidad radical de la demanda ."]'),
('DP-004', 'Notificaciones', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Acto formal por el cual se comunica a las partes el contenido de las resoluciones judiciales, para que produzcan efecto. La primera notificaci¾n de la demanda debe ser personal al demandado, y en general ninguna resoluci¾n genera efecto si no ha sido notificada conforme a la ley.', 'Ej.: El auto de apertura de prueba se notifica por cÚdula al abogado del demandado en su domicilio registrado. Solo desde esa notificaci¾n comienza a correr el plazo probatorio.', 'Arts. 38 y ss. CPC (toda resoluci¾n surte efecto con notificaci¾n legal', 'requisitos de notificaci¾n personal, por cÚdula, por avisos, etc.)', '', '["Corte Suprema, 02.07.2019, Rol 13.122-2019 (anul¾ todo lo obrado tras notificaci¾n defectuosa, reiterando que la notificaci¾n invßlida vulnera la bilateralidad de la audiencia)"]'),
('DP-005', 'Plazos Procesales', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Periodos de tiempo fijados por la ley o el tribunal para realizar actos procesales. Por regla general son fatales (su inobservancia extingue el derecho a actuar) y se computan en dÝas hßbiles judiciales. Comienzan a correr desde la medianoche del dÝa de la notificaci¾n respectiva, salvo rÚgimen especial de ampliaci¾n por distancia.', 'Ej.: En un juicio ordinario civil, el demandado tiene 15 dÝas para contestar la demanda si fue notificado dentro del territorio jurisdiccional del tribunal', 'vencido ese plazo sin contestaci¾n, queda en rebeldÝa.', 'Arts. 258-259 CPC (plazos para contestar demanda seg·n distancia)', '', '["Art. 66 CPC (plazos fatales y prorrogables)"]'),
('DP-006', 'Jurisdicci¾n', 'Derecho Procesal', 'Disposiciones Orgßnicas (Tribunales)', 'Poder-deber del Estado, radicado exclusivamente en los tribunales de justicia, de conocer, juzgar y hacer cumplir lo juzgado en causas de naturaleza contenciosa o asuntos no contenciosos sometidos a su conocimiento. Es de orden p·blico y emana de la soberanÝa (Art. 76 Constituci¾n).', 'Ej.: Un conflicto civil por incumplimiento contractual es resuelto por el juez civil competente, ejerciendo la jurisdicci¾n que la ley le confiere.', 'Art. 1 C¾digo Orgßnico de Tribunales (COT)', '', '', '["Se contrapone al ejercicio privado de autotutela: la jurisdicci¾n monopoliza la soluci¾n de litigios, pero su alcance es limitado por la inmunidad soberana extranjera o fueros especiales (crÝtica: ciertos actos administrativos con efecto jurisdiccional podrÝan lesionar la exclusividad)", "Discusi¾n sobre ôjurisdicci¾n voluntariaö: algunos la excluyen de la funci¾n jurisdiccional por no haber litigio, mientras otros la incluyen por involucrar actuaci¾n de tribunales."]'),
('DP-007', 'Competencia', 'Derecho Procesal', 'Disposiciones Orgßnicas (Tribunales)', '┴mbito dentro del cual cada tribunal puede ejercer jurisdicci¾n, determinado por factores establecidos en la ley: materia (asunto de que se trata), cuantÝa (valor econ¾mico), territorio (lugar), grado (instancia) y fuero (privilegio de determinadas autoridades). La competencia absoluta refiere a materia, cuantÝa y fuero', 'la relativa al territorio del tribunal.', 'Ej.: Un juicio civil de cobro por ~$5.000 USD se ventila ante un Juzgado de Letras en lo Civil (materia civil, cuantÝa sobre 10 UTM), con competencia en la comuna del domicilio del demandado (territorio).', 'Arts. 108-115 COT (competencia por materia y cuantÝa)', '', '["Arts. 134-139 COT (reglas de competencia territorial y pr¾rroga)"]'),
('DP-008', 'Juez Natural', 'Derecho Procesal', 'Disposiciones Orgßnicas (Tribunales)', 'Principio fundamental seg·n el cual toda persona tiene derecho a ser juzgada por tribunales ordinarios previamente establecidos por la ley, competentes para la materia y territorio del caso. Se prohÝben los tribunales de excepci¾n o comisiones especiales creados ex post hecho.', 'Ej.: Un funcionario acusado de un delito com·n serß juzgado por el tribunal penal ordinario que se±ala la ley y no por una comisi¾n ad-hoc. Del mismo modo, un civil no puede ser juzgado por un tribunal militar si la ley no lo contempla (resguardo del juez natural).', 'Art. 19 N░3 Constituci¾n PolÝtica', 'Art. 2 COT (proscribe comisiones especiales, exige tribunal establecido con anterioridad)', '', '[]'),
('DP-009', 'Tribunales Ordinarios vs. Especiales', 'Derecho Procesal', 'Disposiciones Orgßnicas (Tribunales)', 'Los tribunales ordinarios son aquellos del Poder Judicial con competencia general (Corte Suprema, Cortes de Apelaciones, tribunales de juicio oral, juzgados de letras y de garantÝa), mientras que los especiales conocen materias especÝficas y se rigen por leyes orgßnicas particulares (juzgados de familia, laborales, militares en tiempo de paz, etc.).', 'Ej.: Un conflicto de familia se ve ante un Juzgado de Familia (tribunal especial)', 'en cambio, un caso civil patrimonial se ventila en un Juzgado de Letras civil (tribunal ordinario).', 'Art. 5 COT (integrantes del Poder Judicial ordinario y enumeraci¾n de tribunales especiales)', '', '[]'),
('DP-010', 'Recusaci¾n e Implicancia', 'Derecho Procesal', 'Disposiciones Orgßnicas (Tribunales)', 'Mecanismos para asegurar la imparcialidad del juez. La implicancia opera de pleno derecho ante causales objetivas tasadas (parentesco cercano con una parte, interÚs en el pleito, etc.), obligando al juez a abstenerse. La recusaci¾n es solicitada por una parte cuando concurre alguna causal legal de desconfianza en la imparcialidad del juez (ej. enemistad grave, amistad Ýntima, interÚs indirecto) y no se ha abstenido voluntariamente.', 'Ej.: En un juicio donde el juez es hermano del demandante, existe causal de implicancia (parentesco de segundo grado) que lo inhabilita automßticamente (Art. 196 COT)', 'si el juez no se aparta, la parte demandada puede deducir recusaci¾n para apartarlo.', 'Arts. 195-200 COT (listas de causales de implicancia y recusaci¾n, p. ej. parentesco, amistad/enemistad manifiesta, haber sido abogado en el caso, etc.)', '', '["CS, 30.07.2018 (Rol 12358-2018): Rechaz¾ recusaci¾n contra ministro de Corte Suprema por ôsentimientos negativosö del recurrente, al no configurar causal legal de implicancia ni probarse infracci¾n a la imparcialidad"]'),
('DP-011', 'Demanda', 'Derecho Procesal', 'Juicio Ordinario de Mayor CuantÝa', 'Acto procesal inicial por el cual el demandante ejercita su pretensi¾n ante el tribunal competente, dando inicio formal al litigio. Debe cumplir requisitos estrictos: designaci¾n del tribunal, individualizaci¾n de las partes y sus domicilios, exposici¾n clara de los hechos y fundamentos de derecho, y peticiones concretas sometidas a fallo.', 'Ej.: En un juicio de cobro de $100 millones, el acreedor presenta una demanda escrita que identifica al deudor, narra el contrato impago, fundamenta en el C¾digo Civil el incumplimiento y solicita condena de pago mßs intereses (cumpliendo las exigencias del Art. 254 CPC).', 'Art. 254 CPC (requisitos de la demanda: tribunal, partes, hechos, fundamentos de derecho, petitorio)', 'Corte Suprema, 08.10.2024 (Rol 20.625-2024, Conadecus c. Santander): Confirm¾ la inadmisibilidad de una demanda colectiva por no contener una exposici¾n clara de los hechos y fundamentos de derecho, reiterando la exigencia del Art. 254 CPC.', '', '["Visiones contrapuestas: una postura formalista exige el estricto cumplimiento de los requisitos (so pena de inadmisibilidad inmediata de la demanda), mientras otra mßs pro actione propugna interpretar con flexibilidad la suficiencia de la narraci¾n fßctica, privilegiando el derecho a la tutela judicial efectiva", "La jurisprudencia reciente oscila: ha declarado inadmisibles libelos imprecisos en demandas colectivas, pero admite subsanaciones menores para evitar sacrificar fondo por la forma."]'),
('DP-012', 'Contestaci¾n de la Demanda', 'Derecho Procesal', 'Juicio Ordinario de Mayor CuantÝa', 'Escrito mediante el cual el demandado responde a la demanda, aceptando o negando los hechos alegados y formulando sus defensas. Debe contener la individualizaci¾n del tribunal y partes, las excepciones dilatorias si las hubiere, la contestaci¾n de fondo con una exposici¾n precisa de los hechos que se admiten o controvierten y los fundamentos jurÝdicos de su defensa, pudiendo incluir ademßs demandas reconvencionales.', 'Ej.: En un juicio por incumplimiento contractual, el demandado contesta negando haber incumplido, ofreciendo su propia versi¾n de los hechos (p. ej., alega caso fortuito) y planteando la excepci¾n de falta de legitimaci¾n activa, todo dentro del plazo legal de 15 dÝas desde la notificaci¾n.', 'Art. 309 CPC (contenido de la contestaci¾n: requisitos similares a la demanda, indicando tribunal, partes, aceptaci¾n o negaci¾n de hechos, defensas de fondo)', '', '', '["Cuesti¾n debatida: si el demandado no contest¾ (rebeldÝa), ┐puede el juez tener por confesados los hechos? En Chile rige que la rebeldÝa no importa aceptaci¾n tßcita de la demanda, debiendo igualmente el actor probar sus dichos (a diferencia de otros sistemas). Jurisprudencia uniforme: la incomparecencia no exime al demandante de acreditar sus hechos constitutivos, aunque se le facilite la prueba al no haber controversia explÝcita ."]'),
('DP-013', 'Conciliaci¾n', 'Derecho Procesal', 'Juicio Ordinario de Mayor CuantÝa', 'Actuaci¾n procesal en la fase inicial del juicio ordinario en que el juez procura que las partes logren un avenimiento. Ocurre normalmente tras la etapa de discusi¾n (demanda y contestaci¾n). El juez de oficio cita a una audiencia de conciliaci¾n y, obrando como amigable componedor, propone f¾rmulas de arreglo. Si no se logra acuerdo total o parcial, se deja constancia y contin·a el juicio.', 'Ej.: En un juicio ordinario sobre indemnizaci¾n de perjuicios, el juez convoca a las partes a una audiencia de conciliaci¾n. Propone que el demandado pague la mitad de lo pedido en un plazo, pero si las partes no aceptan, se certifica el fracaso de la conciliaci¾n y se prosigue a fijar los puntos de prueba.', 'Arts. 262-264 CPC (obligatoriedad de citar a conciliaci¾n', 'papel del juez como componedor', '', '["acta de avenimiento si hay acuerdo)"]'),
('DP-014', 'Periodo Probatorio', 'Derecho Procesal', 'Juicio Ordinario de Mayor CuantÝa', 'Etapa del juicio, abierta mediante resoluci¾n ôautos a pruebaö, en la que las partes rinden la prueba de los hechos controvertidos fijados por el tribunal. El tÚrmino probatorio ordinario es com·n para ambas partes y dura 20 dÝas hßbiles cuando la prueba debe rendirse dentro de la jurisdicci¾n, con posibles ampliaciones si se requiere practicar diligencias fuera del territorio o en el extranjero.', 'Ej.: En un juicio ordinario, fijados como puntos de prueba el incumplimiento del contrato y sus da±os, las partes disponen de 20 dÝas para presentar testigos, peritajes y documentos pertinentes', 'si se requieren testigos que residen lejos, el tribunal concede 30 dÝas adicionales por la distancia (tabla de emplazamiento).', 'Arts. 328-329 CPC (duraci¾n del tÚrmino probatorio ordinario y aumento por distancia)', '', '[]'),
('DP-015', 'Sentencia', 'Derecho Procesal', 'Juicio Ordinario de Mayor CuantÝa', 'Decisi¾n judicial que pone fin al juicio, resolviendo las pretensiones planteadas. La sentencia definitiva debe contener, seg·n el Art. 170 CPC: la designaci¾n del tribunal y partes, consideraciones de hecho y de derecho que fundan el fallo, y la parte dispositiva que acoge o rechaza las peticiones. Se exige que sea fundada, congruente con lo litigado y dictada por juez imparcial.', 'Ej.: En un juicio ordinario sobre incumplimiento contractual, la sentencia definitiva expone los hechos probados (existencia del contrato, incumplimiento del demandado), los fundamentos jurÝdicos (art. 1545 CC, fuerza obligatoria de contratos) y decide acoger la demanda, condenando al demandado a pagar cierta suma, con costas.', 'Arts. 158 y 170 CPC (definici¾n de sentencia definitiva y requisitos formales de toda sentencia: motivaciones y parte resolutiva)', 'Corte Suprema, 21.01.2019, Rol 40166-2017: Invalid¾ de oficio una sentencia de la CA de Talca por falta de fundamentaci¾n, reiterando que la ausencia de consideraciones de hecho o derecho esenciales infringe el Art. 170 CPC y constituye causal de casaci¾n en la forma.', '', '["Se plantea el dilema entre exigencia de motivaci¾n vs. brevedad: la jurisprudencia ha anulado fallos por motivaci¾n aparente o insuficiente, enfatizando el derecho a una sentencia razonada (debido proceso)", "Sin embargo, se advierte riesgo de ôjurisprudencia de mÚritoö si la Corte Suprema eval·a excesivamente la fundamentaci¾n, invadiendo competencias del fondo. La discusi¾n se refleja en c¾mo distinguir entre falta de consideraciones (vicio formal) y mera divergencia en la valoraci¾n probatoria (no casable en la forma)."]'),
('DP-016', 'TÝtulo Ejecutivo', 'Derecho Procesal', 'Juicios Ejecutivos', 'Documento al cual la ley confiere mÚrito suficiente para demandar coactivamente una obligaci¾n en sede ejecutiva, sin necesidad de juicio declarativo previo. Debe contener una obligaci¾n clara, actualmente exigible y liquidable. Ejemplos tÝpicos: una sentencia firme condenatoria, un pagarÚ o cheque protestado, una escritura p·blica reconociendo deuda, etc., enumerados en el Art. 434 CPC.', 'Ej.: Un pagarÚ vencido y debidamente protestado, firmado ante notario, es un tÝtulo ejecutivo contra el deudor por el capital e intereses allÝ consignados.', 'Art. 434 CPC (enumeraci¾n de tÝtulos con fuerza ejecutiva: sentencias firmes, instrumentos p·blicos, instrumentos privados reconocidos ante juez, cheques, pagarÚs con requisitos, etc.)', 'Corte Suprema, 14.01.2026 (Rol 13.345-2025): Declar¾ que un pagarÚ firmado bajo condici¾n suspensiva carece de mÚrito ejecutivo mientras la condici¾n no se cumpla, reiterando que solo obligaciones actualmente exigibles pueden ejecutarse.', '', '["Debate jurisprudencial sobre tÝtulos incompletos o alterados: por ej., pagarÚs con espacios en blanco llenados sin autorizaci¾n han sido negados como ejecutivos por la Corte (falta de exigibilidad clara)", "TambiÚn se discute la validez ejecutiva de contratos con clßusulas aceleratorias automßticas: tendencia judicial a aceptarlos como ejecutivos siempre que la clßusula estÚ pactada expresamente, mientras la doctrina advierte riesgo de extender la vÝa ejecutiva a supuestos no previstos estrictamente en la ley."]'),
('DP-017', 'Mandamiento de Ejecuci¾n y Embargo', 'Derecho Procesal', 'Juicios Ejecutivos', 'Resoluci¾n inicial que despacha la ejecuci¾n forzada. Contiene la orden al receptor judicial de requerir de pago al deudor por la suma demandada y, no pagando, embargar bienes suficientes para responder. Su notificaci¾n personal al ejecutado es requisito esencial. Marca el comienzo del procedimiento de apremio (embargos, realizaci¾n de bienes).', 'Ej.: Admitida a trßmite la demanda ejecutiva fundada en un pagarÚ, el tribunal emite mandamiento ordenando al receptor: ôRequÝÚrase de pago al deudor X por $10 millones y c·mplase embargo sobre sus bienes suficientes si no pagaö. El receptor concurre al domicilio del deudor, lo notifica y embarga bienes (ej. un vehÝculo) ante la falta de pago inmediato.', 'Arts. 442-443 CPC (contenido del mandamiento: requerimiento de pago personal y embargo en caso de no pago)', '', '', '["Un tema prßctico es el cumplimiento efectivo de la notificaci¾n personal: la jurisprudencia exige agotar diligencias para notificar personalmente el mandamiento, ya que de ello depende vßlidamente la traba de embargo y el curso de la ejecuci¾n. Se discute si la notificaci¾n por cÚdula del mandamiento (permitida tras intento fallido personal) vulnera garantÝas del deudor"]'),
('DP-018', 'Excepciones del Juicio Ejecutivo', 'Derecho Procesal', 'Juicios Ejecutivos', 'Defensas especÝficas y taxativas que el ejecutado puede oponer dentro del breve plazo legal (4 dÝas) para paralizar o invalidar la ejecuci¾n. Estßn enumeradas en el Art. 464 CPC e incluyen, entre otras: incompetencia del tribunal, incapacidad del demandante, litispendencia, ineptitud del libelo, falsedad o falta de requisitos del tÝtulo, pago o extinci¾n de la obligaci¾n, prescripci¾n, cosa juzgada, etc.. Solo estas excepciones pueden alegarse en sede ejecutiva.', 'Ej.: Frente a una ejecuci¾n hipotecaria, el deudor puede oponer la excepci¾n de pago (numeral 9 del Art. 464 CPC) acreditando que ya cancel¾ la deuda, o la excepci¾n de prescripci¾n de la acci¾n ejecutiva (numeral 17) si ha transcurrido el plazo legal, con lo cual busca que se termine el juicio ejecutivo..', 'Art. 464 CPC (numerales 1░ al 18░, listado completo de excepciones admisibles en juicio ejecutivo)', '', '', '["La jurisprudencia es estricta en la taxatividad: no admite defensas fuera del catßlogo del Art. 464. Por ej., intentos de oponer ôabuso de derechoö o ôlesi¾n enormeö como excepci¾n han sido rechazados por no figurar en la lista legal. CrÝtica doctrinal: el sistema puede ser excesivamente rÝgido, impidiendo alegar situaciones de injusticia no previstas expresamente. Sin embargo, los tribunales se±alan que el ejecutado conserva la vÝa ordinaria (juicio de conocimiento posterior) para discutir aspectos no incluidos en las excepciones ejecutivas, salvaguardando el debido proceso sin desnaturalizar la ejecuci¾n."]'),
('DP-019', 'Remate', 'Derecho Procesal', 'Juicios Ejecutivos', 'Acto de subasta p·blica de los bienes embargados al ejecutado, ordenado por sentencia de remate o mandamiento firme, para convertirlos en dinero y pagar al acreedor con el producto. Debe realizarse con publicidad y bajo las bases fijadas por el tribunal (mÝnimo, forma de pago, cauciones). Se anuncia mediante avisos en diarios locales al menos por 4 veces antes de la fecha de subasta.', 'Ej.: En una ejecuci¾n hipotecaria, una vez dictada la sentencia de remate, se publica en un diario de la comuna un aviso indicando que el inmueble del deudor se subastarß tal dÝa en el juzgado, con postura mÝnima de $50 millones. El dÝa del remate, se presentan postores, se adjudica al mejor oferente y este debe consignar el precio seg·n lo establecido.', 'Arts. 488-495 CPC (procedimiento del remate: publicaciones, posturas, pago del precio, acta de remate, sanciones por incumplimiento del adjudicatario)', '', '', '["Problemßticas frecuentes: remates desiertos (sin postores) obligan a rebajar mÝnimum o a prenda pretoria en favor del acreedor, lo cual se ha criticado como posible enriquecimiento del ejecutante. La jurisprudencia ha abordado tambiÚn nulidades de remate por vicios en la publicidad o colusi¾n entre postores: ha dejado sin efecto subastas cuando no se cumpli¾ con los avisos legales o hubo maquinaciones para bajar el precio, ponderando el equilibrio entre seguridad jurÝdica del remate y protecci¾n del deudor contra liquidaciones irrisorias."]'),
('DP-020', 'TercerÝas', 'Derecho Procesal', 'Juicios Ejecutivos', 'Intervenciones de terceros en un juicio ejecutivo para reclamar derechos propios sobre los bienes embargados o el producto de ellos. Solo se admiten en cuatro casos: 1) tercerÝa de dominio (tercero alega ser due±o de los bienes embargados)', '2) de posesi¾n (alega tenencia legÝtima)', '3) de prelaci¾n (tercero acreedor con crÚdito privilegiado que pide ser pagado antes)', '4) de pago (tercero solicita se le pague a Úl con lo obtenido).', '', '["Ej.: A un ejecutado se le embarga un vehÝculo, pero un tercero presenta una tercerÝa de dominio afirmando que el auto le pertenece (p. ej., por compraventa anterior). El tercerista deberß probar su dominio en un juicio incidental"]'),
('DP-021', 'Recurso de Apelaci¾n', 'Derecho Procesal', 'Recursos Procesales', 'Medio de impugnaci¾n ordinario que permite a la parte agraviada por una resoluci¾n judicial obtener su revisi¾n por el tribunal superior. El fin de la apelaci¾n es que el superior corrija con arreglo a derecho la resoluci¾n del inferior, pudiendo confirmar, revocar o modificar lo decidido. En materia civil procede contra sentencias definitivas de primera instancia y ciertas interlocutorias, seg·n reglas legales.', 'Ej.: En un juicio civil, la sentencia del Juzgado de Letras que rechaza la demanda puede ser apelada por el demandante ante la Corte de Apelaciones respectiva, la cual reexaminarß el caso y dictarß su propio fallo confirmatorio o revocatorio del de primera instancia.', 'Arts. 186-193 CPC (objeto, plazo y efectos de la apelaci¾n', 'apelaciones en ambos efectos o solo devolutivo seg·n el caso)', '', '[]'),
('DP-022', 'Recurso de Casaci¾n en la Forma', 'Derecho Procesal', 'Recursos Procesales', 'Recurso extraordinario que busca invalidar una sentencia viciada por errores procedimentales graves. Se funda en causales taxativas (Art. 768 CPC), como: tribunal incompetente, ultra petita (fallo otorga mßs de lo pedido), sentencia incongruente o falta de fundamentaci¾n, entre otras. Apunta a anular el fallo por infracci¾n a las formas sustanciales del procedimiento.', 'Ej.: Tras una sentencia de segunda instancia que omiti¾ pronunciarse sobre una excepci¾n sustancial alegada (omisi¾n que vulnera el debido proceso), la parte afectada interpone casaci¾n en la forma ante la Corte Suprema invocando la causal del N░5 del Art. 768 CPC (omisi¾n de consideraciones), solicitando la nulidad del fallo y la emisi¾n de uno nuevo correctamente motivado.', 'Arts. 767-768 CPC (procedencia de casaci¾n en sentencias inapelables', 'causales formales especÝficas)', '', '["Corte Suprema, 21.01.2019, Rol 40166-2017: Acogi¾ de oficio casaci¾n en la forma contra una sentencia de la CA Talca, por faltar las consideraciones de hecho y derecho (causal del Art. 768 N░5 CPC), invalidando el fallo y ordenando sentencia nueva."]'),
('DP-023', 'Recurso de Casaci¾n en el Fondo', 'Derecho Procesal', 'Recursos Procesales', 'Recurso extraordinario ante la Corte Suprema, procedente contra sentencias definitivas o interlocutorias inapelables de tribunales superiores, cuando en ellas se ha infringido la ley sustantiva y dicha infracci¾n ha influido substancialmente en lo dispositivo del fallo. Busca la correcta aplicaci¾n del derecho objetivo, mßs que la revisi¾n de los hechos del caso.', 'Ej.: Una Corte de Apelaciones confirma una sentencia pero aplica err¾neamente una norma de prescripci¾n, calculando mal el plazo. La parte perjudicada interpone casaci¾n en el fondo por infracci¾n de ley (artÝculo de prescripci¾n del CC) ante la Corte Suprema, para que anule lo resuelto y dicte sentencia conforme a la norma bien interpretada.', 'Arts. 766-772 CPC (requisitos y causales de casaci¾n de fondo: quebrantamiento de ley sustancial decisiva)', 'CS, 28.02.2020, Rol 29.411-2019: Acogi¾ casaci¾n en el fondo y anul¾ sentencia laboral que habÝa aplicado incorrectamente la norma de indemnizaci¾n por a±os de servicio, corrigiendo el cßlculo a favor del trabajador', '', '["Existe fricci¾n entre el rol unificador de la Corte Suprema y el respeto a la soberanÝa del tribunal de instancia en la valoraci¾n de la prueba. La casaci¾n en el fondo no puede revisar hechos, solo derecho, pero en ocasiones la lÝnea se difumina: crÝticos acusan a la Corte de revalorar implÝcitamente prueba so pretexto de error de derecho. A su vez, se plantea instaurar un recurso de unificaci¾n de jurisprudencia mßs amplio (como existe en laboral) para resolver discrepancias sin necesidad de invocar errores in procedendo o in iudicando estrictos."]'),
('DP-024', 'Recurso de Queja', 'Derecho Procesal', 'Recursos Procesales', 'Recurso de carßcter disciplinario que se interpone ante una Corte superior (Corte de Apelaciones o Suprema, seg·n el caso) para corregir faltas o abusos graves cometidos por un juez en la dictaci¾n de una resoluci¾n no susceptible de recursos ordinarios ni extraordinarios. Su objetivo es tutelar la recta administraci¾n de justicia sancionando al juez infractor y enmendando el perjuicio causado por su resoluci¾n.', 'Ej.: Una Corte de Apelaciones dicta una sentencia definitiva inapelable en un recurso de protecci¾n con manifiesto error jurÝdico y con posible arbitrariedad. La parte afectada presenta recurso de queja ante la Corte Suprema acusando falta grave en la decisi¾n, solicitando se deje sin efecto el fallo y se sancione disciplinariamente a los ministros que incurrieron en el abuso.', 'Art. 545 COT (procede queja por falta o abuso grave en sentencia interlocutoria o definitiva inapelable)', 'CS, 24.11.2025, Rol 250.587-2023: Rechaz¾ queja contra una Corte que declar¾ prescrita una acci¾n penal, enfatizando que una mera discrepancia en la interpretaci¾n de la ley no configura por sÝ sola falta o abuso grave que dÚ lugar a la queja.', '', '["La Corte Suprema ha limitado el alcance de la queja: ha reiterado que no es una ôtercera instanciaö para revisar el fondo de los asuntos, sino un mecanismo estrictamente disciplinario. Solo procede ante actuaciones judiciales aberrantes sin remedio recursal. Se debate si su uso actual desborda lo disciplinario (corrigiendo errores jurÝdicos bajo la etiqueta de abuso grave) o si, por el contrario, la CS ha sido correcta al restringirlo, como en fallos donde declara improcedente la queja cuando existen recursos legales disponibles o la cuesti¾n es de mera discrepancia jurÝdica."]'),
('DP-025', 'Recurso de Reposici¾n', 'Derecho Procesal', 'Recursos Procesales', 'Medio de impugnaci¾n horizontal, por el cual una parte solicita al mismo tribunal que dict¾ una resoluci¾n de trßmite (autos, decretos o ciertas interlocutorias) que la reconsidere o enmiende, por estimarla err¾nea o perjudicial. Se interpone dentro de un breve plazo (generalmente 3 dÝas) desde la notificaci¾n de la resoluci¾n y puede ser con o sin ôapelaci¾n en subsidioö.', 'Ej.: El juez dicta una resoluci¾n que rechaza por extemporßneo un escrito de prueba', 'la parte afectada interpone reposici¾n dentro de 3 dÝas argumentando que present¾ el escrito en plazo hßbil, pidiendo al mismo juez que revoque su decisi¾n. Si el juez rechaza la reposici¾n, queda expedita la apelaci¾n subsidiaria si se interpuso.', 'Art. 81 CPC (procedencia de reposici¾n contra autos y decretos dentro de tercero dÝa)', '', '["Art. 362 C¾digo Procesal Penal (reposiciones en procedimiento penal)"]'),
('DP-026', 'Principio Acusatorio', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'Eje del nuevo sistema penal chileno que separa las funciones de investigar, acusar y juzgar. La persecuci¾n penal la dirige en forma exclusiva el Ministerio P·blico, mientras un juez de garantÝa imparcial controla la legalidad del procedimiento y otro tribunal (Tribunal de Juicio Oral) resuelve sobre la culpabilidad. Implica oralidad, publicidad, contradicci¾n y que el juez no act·a de oficio en la investigaci¾n (a diferencia del antiguo sistema inquisitivo).', 'Ej.: Ante un delito, el fiscal re·ne evidencias e imputa cargos, el juez de garantÝa vela por los derechos del imputado (p. ej., autorizando cautelares si proceden) y finalmente un tribunal oral colegiado decide la condena o absoluci¾n en juicio. El juez no investiga por sÝ mismo, respetando la divisi¾n acusador/juzgador.', 'Arts. 1, 3 C¾digo Procesal Penal (CPP) (juicio previo ante tribunal imparcial', 'investigaci¾n a cargo exclusivo del MP)', '', '[]'),
('DP-027', 'Formalizaci¾n de la Investigaci¾n', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'Acto procesal mediante el cual el fiscal comunica al imputado, en audiencia ante el juez de garantÝa, que se desarrolla una investigaci¾n penal en su contra por hechos determinados. A partir de la formalizaci¾n, el imputado adquiere derechos plenos de defensa (acceso a la carpeta investigativa, solicitar diligencias) y el proceso penal entra en la etapa formal. No es una acusaci¾n, sino un hito intermedio que posibilita cautelares y fija el punto de inicio del procedimiento penal formal.', 'Ej.: En un caso de robo, el fiscal solicita audiencia de formalizaci¾n. En dicha audiencia, le indica al imputado ôse le investiga por robo ocurrido el 5 de marzo enàö, ante el juez. Desde entonces, el imputado puede pedir pruebas, y el fiscal ya puede solicitar medidas cautelares (p. ej., prisi¾n preventiva).', 'Art. 229 CPP (define la formalizaci¾n como la comunicaci¾n al imputado, ante juez, de la existencia de una investigaci¾n en su contra)', '', '', '["La formalizaci¾n ha generado debate respecto a su oportunidad: fiscalÝa suele demorarse hasta reunir antecedentes suficientes, lo que para la defensa puede implicar investigaciones ôsecretasö prolongadas. El Tribunal Constitucional ha se±alado que la formalizaci¾n marca el inicio del plazo de investigaci¾n y del control judicial, garantizando derechos del imputado. TambiÚn se discute su no-recurribilidad: al no ser resoluci¾n, no admite recursos, lo que ha sido criticado por limitar el control"]'),
('DP-028', 'Medidas Cautelares Personales', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'Restricciones impuestas al imputado durante la investigaci¾n para asegurar fines del proceso (comparecencia, seguridad de la sociedad o de la vÝctima). Van desde la prisi¾n preventiva (privaci¾n de libertad) hasta medidas menos gravosas: arresto domiciliario, prohibici¾n de acercarse a la vÝctima, firma peri¾dica, arraigo (prohibici¾n de salir del paÝs), entre otras. La prisi¾n preventiva procede solo si las demßs resultan insuficientes y existieren antecedentes de peligro de fuga o de peligro para la seguridad.', 'Ej.: A un imputado por robo con intimidaci¾n, sin antecedentes penales, el juez de garantÝa le decreta arresto domiciliario nocturno y arraigo nacional en lugar de prisi¾n preventiva, al considerar que con esas medidas se asegura su sujeci¾n al procedimiento y la seguridad de la vÝctima.', 'Arts. 140-146 CPP (presupuestos de la prisi¾n preventiva: indicios de delito y necesidad por peligro de fuga o para la sociedad)', 'Art. 155 CPP (medidas cautelares menos gravosas)', '', '[]'),
('DP-029', 'Audiencia de Preparaci¾n de Juicio Oral', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'TambiÚn llamada etapa intermedia, es la audiencia ante el juez de garantÝa en que se depura el caso que irß a juicio oral. Tras la formalizaci¾n y cierre de la investigaci¾n, el fiscal presenta la acusaci¾n y en esta audiencia se discuten las pruebas que cada parte pretende llevar al juicio. El juez resuelve sobre su admisibilidad, excluyendo pruebas ilÝcitas o impertinentes, y dicta el auto de apertura de juicio oral con los hechos precisos de acusaci¾n y la n¾mina de prueba admitida.', 'Ej.: En un caso de lesiones graves, en la audiencia preparatoria el defensor se opone a la incorporaci¾n de cierta declaraci¾n por haber sido obtenida sin abogado (prueba ilÝcita). El juez de garantÝa acoge la objeci¾n y excluye esa declaraci¾n. Luego de debatir todas las pruebas, el juez dicta auto de apertura, estableciendo quÚ pruebas sÝ se rendirßn ante el tribunal oral.', 'Arts. 259-274 CPP (acusaci¾n y preparaci¾n del juicio oral: intercambio de escritos acusatorios, audiencia para acuerdos probatorios, admisibilidad de prueba y auto de apertura)', '', '', '["Esta fase equilibra garantÝas y eficiencia: permite filtrar prueba ilegal o irrelevante antes del juicio. Sin embargo, se debate si los jueces de garantÝa a veces aplican un estßndar demasiado laxo o estricto al excluir pruebas. Por ej., jurisprudencia diversa en criterios de exclusi¾n de testigos no individualizados en acusaci¾n ha generado incertidumbre. TambiÚn se analiza la conciliaci¾n en delitos no graves durante esta etapa: algunos la fomentan para descongestionar (ej. acuerdo reparatorio), mientras otros advierten que puede trivializar la acci¾n penal. La tendencia apunta a fortalecer esta audiencia como espacio clave de preparaci¾n, enfatizando principios de descubrimiento probatorio recÝproco y lealtad procesal."]'),
('DP-030', 'Juicio Oral', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'Fase culminante del proceso penal, donde un tribunal colegiado (3 jueces profesionales) conoce p·blicamente, en forma oral y contradictoria, la prueba sobre la acusaci¾n formulada, para dictar veredicto y sentencia. Rige la inmediaci¾n (los jueces deben presenciar directamente la rendici¾n de pruebas) y la continuidad (audiencia ininterrumpida hasta conclusi¾n). El juicio oral es p·blico, salvo excepciones para proteger bienes jurÝdicos sensibles.', 'Ej.: En un juicio oral por robo, comparecen los testigos de cargo y descargo, se presentan peritajes (todo en audiencia oral). Los jueces escuchan los alegatos finales de fiscal y defensa y luego deliberan para emitir veredicto absolutorio o condenatorio, y en caso de condena dictan la sentencia con la pena correspondiente.', 'Arts. 280-303 CPP (principios del juicio oral: publicidad, oralidad, inmediaci¾n, concentraci¾n', 'desarrollo: orden de prueba, interrogatorios, alegatos finales)', '', '[]');
